import os
import torch


class Config:
    """
    Central configuration for the Phrase Similarity pipeline.
    """

    # --- General Configuration ---
    seed = 42
    debug = False  # Set to True to run on a small subset of data
    debug_sample_size = 100
    num_workers = 4  # Number of dataloader workers

    # --- Paths ---
    # Input Metadata (Generated by the metadata script)
    train_path = "./metadata/train.csv"
    val_path = "./metadata/val.csv"
    test_path = "./metadata/test.csv"

    # Working Directory (For caching processed data and saving models)
    output_dir = "./working/idea_3"

    # Optional: Path to CPC titles for context enrichment
    # (Assuming standard location if available, otherwise pipeline handles missing file)
    cpc_codes_path = "./input/cpc-data/titles.csv"

    # --- Model Configuration ---
    model_name = "microsoft/deberta-v3-large"
    max_length = 140  # Sufficient for Context + Anchor + Target
    target_size = 5  # Number of classes: 0.0, 0.25, 0.5, 0.75, 1.0
    fc_dropout = 0.2  # Dropout for the final classification head

    # --- Training Configuration ---
    n_folds = 5
    epochs = 5
    train_batch_size = 8  # Adjusted for A100 40GB with Large model
    valid_batch_size = 16
    gradient_accumulation_steps = 1
    max_grad_norm = 1000.0

    # --- Optimizer & Scheduler ---
    learning_rate = 2e-5
    min_lr = 1e-6
    weight_decay = 0.01
    eps = 1e-6
    betas = (0.9, 0.999)
    scheduler_type = "cosine"
    warmup_ratio = 0.1

    # --- Adversarial Weight Perturbation (AWP) ---
    use_awp = True
    awp_lr = 1e-4
    awp_eps = 1e-2
    awp_start_epoch = 1  # Start AWP after the first epoch

    # --- Hardware ---
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    @classmethod
    def setup(cls):
        """
        Ensures the output directory exists.
        """
        os.makedirs(cls.output_dir, exist_ok=True)


# Initialize the configuration environment
Config.setup()
